from pathlib import Path
import tempfile
import threading
import unittest

from tools.can_dashboard import model, sources


PEAK_TRC = """;$FILEVERSION=1.1
;$STARTTIME=46250.0
;
; Generated by PCAN-View v5.3
     1)         2.6  Rx         0180  8  00 10 00 00 00 00 00 00
     2)        12.8  Rx         06F0  8  08 01 02 03 04 05 06 07
     3)        13.0  Error      0008  4  00 19 08 08
"""


class ReplaySourceTest(unittest.TestCase):
    def replay(self, name, content):
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / name
            path.write_text(content, encoding="ascii")
            events = []
            sources.run_replay(
                path,
                threading.Event(),
                events.append,
                speed=1_000_000,
            )
            return events

    def test_peak_trc_11_replay_preserves_frame_metadata(self):
        events = self.replay("capture.trc", PEAK_TRC)
        frames = [
            event for event in events if isinstance(event, model.FrameRecord)
        ]
        self.assertEqual(
            [frame.arbitration_id for frame in frames],
            [0x180, 0x6F0, 0],
        )
        self.assertEqual(frames[0].timestamp, 0.0026)
        self.assertEqual(frames[1].data, bytes.fromhex("0801020304050607"))
        self.assertTrue(frames[2].is_error_frame)
        self.assertEqual(
            events[-1],
            sources.SourceStatus("stopped", "replay complete"),
        )

    def test_compact_candump_replay_remains_supported(self):
        events = self.replay(
            "capture.log",
            "(12.500000) can0 6F0#0801020304050607\n",
        )
        frames = [
            event for event in events if isinstance(event, model.FrameRecord)
        ]
        self.assertEqual(len(frames), 1)
        self.assertEqual(frames[0].arbitration_id, 0x6F0)
        self.assertEqual(frames[0].timestamp, 12.5)


if __name__ == "__main__":
    unittest.main()
